{
 "criticisms": [
  {
   "element": "Desired orders",
   "quote": "Investment_sensitivity * Profit_signal",
   "kind": "information",
   "why": "The rule never reads Boats_on_order. Owners who talk to the yards know how many boats are already being built. Ignoring them (a supply line weight of zero) lets orders run on for a whole build time after profits turn.",
   "suggestion": "Subtract a share of the boats on order, as in the supply line of Stock Management (stockmgmt), or record that owners ignore the order book as an assumption to test."
  },
  {
   "element": "Desired orders",
   "quote": "Fleet * (",
   "kind": "other",
   "why": "Orders are proportional to the fleet, so an empty fishery attracts no boats however rich the stock. Real fisheries draw entrants from outside.",
   "suggestion": "Add an entry term that does not depend on the fleet, or state that entry from outside is beyond the boundary."
  },
  {
   "element": "Ordering",
   "quote": "1000000",
   "kind": "constant",
   "why": "A sentinel number stands for 'no cap'. It repeats the default of Licence cap without a name, and a cap of a million boats reads like a real setting in a parameter table.",
   "suggestion": "Name it No cap, or switch the cap on and off with a 0 or 1 switch, as Quota on does."
  },
  {
   "element": "Ordering",
   "quote": "- Fleet - Boats_on_order",
   "kind": "information",
   "why": "The licensing authority counts the registered fleet and the boats on order. Both are in its own register, so this part of the rule uses information it has.",
   "suggestion": "None: a confirmation."
  },
  {
   "element": "Profit signal",
   "quote": "Perceived_profit / (Variable_cost + Fixed_cost)",
   "kind": "units",
   "why": "EUR thousand/boat/year divided by EUR thousand/boat/year is a fraction, as declared. The units balance.",
   "suggestion": "None: a confirmation."
  },
  {
   "element": "Updating profit",
   "quote": "(Catch_per_boat * Price - Perceived_profit)",
   "kind": "information",
   "why": "Owners perceive revenue, not profit: the costs are missing, so perceived profit runs above the true profit by the full cost of a boat and investment is too strong.",
   "suggestion": "Smooth Profit_per_boat instead of revenue."
  },
  {
   "element": "Investment sensitivity",
   "quote": "0.25",
   "kind": "constant",
   "why": "The constant that sets how fast the fleet grows on profit has no stated source, and the size of the boom depends on it.",
   "suggestion": "Estimate it from records of orders and accounts, and carry a range, say 0.125 to 0.5 a year, into the tests."
  }
 ]
}
